set-variable.value:
@{
            var existing = context.Variables.ContainsKey("existingUsage")
                           && context.Variables["existingUsage"] != null
                ? JObject.Parse((string)context.Variables["existingUsage"])
                : new JObject();
            var model = context.Api.Name;
            if (existing[model] == null) existing[model] = new JObject();
            var m = (JObject)existing[model];
            m["used"]  = (m["used"]?.Value<int>() ?? 0) + (int)context.Variables["tokensUsed"];
            m["limit"] = 5000000; // ← set this to match your token-quota value
            return existing.ToString();
        }
